const d = $json.documents;
const verified = d.filter(x => x.verified).length;
const ocrConfidence = d.length ? Math.round(60 + 40 * (verified / d.length)) : 40;
return [{ json: { ...$json, ocrConfidence, documentsVerified: d.length > 0 && verified === d.length } }];

const disputed = $json.property.status === 'disputed';
const fraudScore = disputed ? 86 : 12;
const fraudBand = fraudScore >= 80 ? 'Critical' : fraudScore >= 50 ? 'Elevated' : fraudScore >= 25 ? 'Watch' : 'Clear';
return [{ json: { ...$json, fraudScore, fraudBand } }];

const supplied = $json.gis?.boundaryAnalysis ?? {};
const boundaryScore = Number.isFinite(supplied.boundaryScore) ? supplied.boundaryScore : (($json.property.boundaryVertices ?? 0) >= 3 ? 70 : 0);
const overlapPercentage = Number.isFinite(supplied.overlapPercentage) ? supplied.overlapPercentage : 0;
const boundaryVerified = supplied.boundaryVerified === true && boundaryScore >= 75 && overlapPercentage >= 85;
return [{ json: { ...$json, boundaryScore, overlapPercentage, boundaryVerified, boundaryConflicts: supplied.conflicts ?? [] } }];

const disputed = $json.property.status === 'disputed';
const riskScore = disputed ? 62 : 18;
return [{ json: { ...$json, riskScore, registryCrossCheck: !disputed && $json.property.status !== 'pending' } }];

const w = { docs: 0.29, boundary: 0.22, risk: 0.2, fraud: 0.29 };
const confidenceScore = Math.round(
  $json.ocrConfidence * w.docs +
  $json.boundaryScore * w.boundary +
  (100 - $json.riskScore) * w.risk +
  (100 - $json.fraudScore) * w.fraud
);
return [{ json: { ...$json, confidenceScore } }];

const s = $json;
const rejected = s.fraudBand === 'Critical' && s.fraudScore >= 80;
const reasons = [];
if (s.fraudScore >= 25) reasons.push('fraud band ' + s.fraudBand);
if (s.confidenceScore < 78) reasons.push('confidence ' + s.confidenceScore + ' below the 78 auto-approve threshold');
if (!s.boundaryVerified) reasons.push('boundary polygon not hardened by field capture');
if (!s.documentsVerified) reasons.push('one or more documents unverified');
return [{ json: { workflowId: 'WF-N8N-' + s.passportId.replace(/[^A-Z0-9]/gi,'') + '-' + Date.now().toString(36).toUpperCase(), propertyId: s.propertyId, passportId: s.passportId, status: rejected ? 'rejected' : 'manual_review', confidenceScore: s.confidenceScore, fraudScore: s.fraudScore, fraudBand: s.fraudBand, boundaryScore: s.boundaryScore, riskScore: s.riskScore, ocrConfidence: s.ocrConfidence, documentsVerified: s.documentsVerified, boundaryVerified: s.boundaryVerified, registryCrossCheck: s.registryCrossCheck, decisionReason: (rejected ? 'Automated approval blocked: ' : 'Human review required — ') + reasons.join('; ') + '.', completedAt: new Date().toISOString(), steps: [ { name: 'Property submitted', status: 'completed' }, { name: 'Document / OCR check', status: s.documentsVerified ? 'completed' : 'attention', score: s.ocrConfidence }, { name: 'Fraud analysis', status: s.fraudScore >= 25 ? 'attention' : 'completed', score: s.fraudScore }, { name: 'Boundary verification', status: s.boundaryVerified ? 'completed' : 'attention', score: s.boundaryScore }, { name: 'Risk analysis', status: s.riskScore >= 45 ? 'attention' : 'completed', score: s.riskScore }, { name: 'Confidence engine', status: 'completed', score: s.confidenceScore }, { name: 'Automated decision', status: 'attention' }, { name: 'Passport readiness', status: 'attention' } ] } }];
